  console.log(`Upload completed: ${event.localId}`, event.result)
})

// Listen to errors
uploadClient.on('upload.error', (event) => {
  console.log(`Upload failed: ${event.localId}`, event.error.message)
})

// Start all uploads
uploadClient.dispatch({ type: 'startAll' })
