s.strong, { children: "Build a file input / dropzone component" }) }), jsx(_components.p, { children: "Add a file input and a drag-and-drop zone:" }), jsxs(_components.div, { "data-dmc-fragment": "", children: [jsx(_components.figcaption, { "data-dmc-title": "", "data-language": "tsx", children: "src/PhotoUploader.tsx" }), jsx(_components.pre, { __dmcRaw__: "import { useUploader } from '@gentleduck/upload'
import { useCallback, useRef, useState } from 'react'

export function PhotoUploader() {
  const { items, dispatch, uploading, completed, failed } = useUploader()
  const inputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)

  const addFiles = useCallback((files: File[]) => {
    if (files.length > 0) {
      dispatch({ type: 'addFiles', files, purpose: 'photo' })
    }
  }, [dispatch])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    const files = Array.from(e.dataTransfer.files)
    addFiles(files)
  }, [addFiles])

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(true)
  }, [])

  const handleDragLeave = useCallback(() => {
    setIsDragging(false)
  }, [])

  return (
    <div>
      {/* Dropzone */}
      <div
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => inputRef.current?.click()}
        style={{
          border: `2px dashed ${isDragging ? '#3b82f6' : '#d1d5db'}`,
          borderRadius: 8,
          padding: 40,
          textAlign: 'center',
          cursor: 'pointer',
          backgroundColor: isDragging ? '#eff6ff' : 'transparent',
          transition: 'all 0.2s',
        }}
      >
        <p>{isDragging ? 'Drop files here' : 'Click or drag files to upload'}</p>
      </div>

      {/* Hidden file input */}
      <input
        ref={inputRef}
        type="file"
        multiple
        accept="image/*"
        style={{ display: 'none' }}
        onChange={(e) => {
          const files = Array.from(e.target.files ?? [])
          addFiles(files)
          e.target.value = ''
        }}
      />

      {/* Upload list */}
      <div style={{ marginTop: 20 }}>
        {items.map((item) => (
          <UploadItemRow key={item.localId} item={item} dispatch={dispatch} />
        ))}
      </div>
    </div>
  )
}
