      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ fileId }),
    })

    if (!res.ok) throw new Error(`Failed to complete upload: ${res.status}`)

    // Your backend returns: { fileId: '...', key: '...', url: '...' }
    return res.json()
  },
